                    "relations": {
                        "items": {
                            "properties": {
                                "onDelete": {
                                    "enum": [
                                        "restrict",
                                        "noAction",
                                        "cascade",
                                        "setNull",
                                        "setDefault"
                                    ]
                                },
                                "onUpdate": {
                                    "enum": [
                                        "restrict",
                                        "noAction",
                                        "cascade",
                                        "setNull",
                                        "setDefault"
                                    ]
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

