{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "required": [
        "updatePeriodMinutes",
        "notificationSettings"
    ],
    "properties": {
        "updatePeriodMinutes": {
            "type": "integer",
            "minimum": 30,
            "default": 30,
            "enum": [
                30,
                60,
                120,
                180,
                720,
                1440
            ],
            "enumNames": [
                "__MSG_every30Minutes__",
                "__MSG_every1Hour__",
                "__MSG_every2Hours__",
                "__MSG_every3Hours__",
                "__MSG_every12Hours__",
                "__MSG_every24Hours__"
            ]
        },
        "notificationSettings": {
            "type": "object",
            "properties": {
                "alertEnabled": {
                    "type": "boolean",
                    "default": true
                },
                "soundEnabled": {
                    "type": "boolean",
                    "default": true
                },
                "enabledSubscriptionIds": {
                    "type": "object",
                    "additionalProperties": {
                        "type": "boolean"
                    },
                    "properties": {
                        "novelous-feed://narou/messages": {
                            "title": "__MSG_narou__: __MSG_narouMessagesFeed__",
                            "type": "boolean",
                            "default": true
                        },
                        "novelous-feed://narou/comments": {
                            "title": "__MSG_narou__: __MSG_narouCommentsFeed__",
                            "type": "boolean",
                            "default": true
                        },
                        "novelous-feed://narou/blog-comments": {
                            "title": "__MSG_narou__: __MSG_narouBlogCommentsFeed__",
                            "type": "boolean",
                            "default": true
                        },
                        "novelous-feed://narou/reviews": {
                            "title": "__MSG_narou__: __MSG_narouReviewsFeed__",
                            "type": "boolean",
                            "default": true
                        },
                        "novelous-feed://kakuyomu/reviews": {
                            "title": "__MSG_kakuyomu__: __MSG_kakuyomuReviewsFeed__",
                            "type": "boolean",
                            "default": true
                        },
                        "novelous-feed://kakuyomu/news-comments": {
                            "title": "__MSG_kakuyomu__: __MSG_kakuyomuNewsCommentsFeed__",
                            "type": "boolean",
                            "default": true
                        }
                    }
                }
            }
        }
    },
    "uiSchema": {
        "ui:order": [
            "updatePeriodMinutes",
            "notificationSettings"
        ],
        "ui:rootFieldId": "options",
        "updatePeriodMinutes": {
            "ui:widget": "hidden"
        },
        "notificationSettings": {
            "ui:order": [
                "soundEnabled",
                "alertEnabled",
                "enabledSubscriptionIds"
            ]
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "required": [
        "projects",
        "drivers"
    ],
    "properties": {
        "projects": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "id": {
                        "type": "string",
                        "pattern": "^[a-z\\d\\./-]+$"
                    },
                    "name": {
                        "type": "string"
                    }
                },
                "required": [
                    "id",
                    "name"
                ],
                "additionalProperties": false
            }
        },
        "releases": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "id": {
                        "$ref": "#/definitions/release_id"
                    },
                    "wiki": {
                        "type": "string"
                    }
                },
                "required": [
                    "id",
                    "wiki"
                ]
            }
        },
        "drivers": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "project_id": {
                        "type": "string"
                    },
                    "vendor": {
                        "type": "string"
                    },
                    "name": {
                        "type": "string"
                    },
                    "description": {
                        "type": "string"
                    },
                    "maintainers": {
                        "type": "array",
                        "items": {
                            "$ref": "#/definitions/user"
                        }
                    },
                    "wiki": {
                        "type": "string"
                    },
                    "releases": {
                        "type": "array",
                        "items": {
                            "$ref": "#/definitions/release_id"
                        }
                    },
                    "ci": {
                        "$ref": "#/definitions/ci"
                    }
                },
                "required": [
                    "project_id",
                    "vendor",
                    "name"
                ],
                "additionalProperties": false
            }
        }
    },
    "definitions": {
        "user": {
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "pattern": "^[^,]+$"
                },
                "email": {
                    "type": "string",
                    "pattern": "^[a-z\\d_\\.-]+@([a-z\\d\\.-]+\\.)+[a-z]+$"
                },
                "irc": {
                    "type": "string",
                    "pattern": "^[\\S]+$"
                },
                "launchpad_id": {
                    "type": "string",
                    "pattern": "^[\\S]+$"
                }
            },
            "required": [
                "name"
            ],
            "additionalProperties": false
        },
        "ci": {
            "type": "object",
            "properties": {
                "id": {
                    "type": "string",
                    "pattern": "^[\\S]+$"
                },
                "success_pattern": {
                    "type": "string"
                },
                "failure_pattern": {
                    "type": "string"
                }
            },
            "required": [
                "id"
            ],
            "additionalProperties": false
        },
        "release_id": {
            "type": "string",
            "pattern": "^[A-Z][a-z]+$"
        }
    }
}

